// One row per page carrying the image, with the source image kept on every
// row so a sheet covering a whole portfolio stays sortable.
const weekOf = $now.toFormat('yyyy-MM-dd');

const clip = (s, n) => {
  const v = String(s || '').replace(/\s+/g, ' ').trim();
  return v.length > n ? v.slice(0, n - 3) + '...' : v;
};

return $input.all().map((item) => {
  const m = item.json;
  return {
    json: {
      'Week of': weekOf,
      'Your image': m.queryImage || '',
      Rank: m.position ?? '',
      'Site using it': m.source || '',
      'Page title': clip(m.title, 180),
      'Page URL': m.url || '',
      Width: typeof m.imageWidth === 'number' ? m.imageWidth : '',
      Height: typeof m.imageHeight === 'number' ? m.imageHeight : '',
    },
  };
});
